import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [first, second] = input;
const n = Number(first);
const a = second.split(" ").map(Number);

const prefix = new Array(n + 1).fill(0);
for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];

// dp[l * n + r] = 区間 [l, r] を 1 匹にまとめる最小コスト
const dp = new Float64Array(n * n);
for (let len = 2; len <= n; len++) {
  for (let l = 0; l + len - 1 < n; l++) {
    const r = l + len - 1;
    let best = Infinity;
    // 最後の合体で、[l, k] と [k+1, r] がまとまる
    for (let k = l; k < r; k++) {
      best = Math.min(best, dp[l * n + k] + dp[(k + 1) * n + r]);
    }
    dp[l * n + r] = best + (prefix[r + 1] - prefix[l]);
  }
}
console.log(dp[n - 1]);
